import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./ILSP7Minimal.sol";
import "./IHupSplits.sol";
import "./IHupDrops.sol";

/**
 * @title Hup Drops
 * @author Hup Labs
 * @notice The Hup NFT launchpad engine — one address per chain. Creators deploy real,
 *         creator-owned collection contracts (LSP7/LSP8 on LUKSO, ERC721/ERC1155 elsewhere)
 *         and sell the primary mint through phases, each with its own window, price, per-wallet
 *         limit, allocation, and gate: open to everyone, the drop's onchain allowlist, LSP26
 *         followers of the creator, members of a Hup community, or holders of an asset. A
 *         creator can append phases to a live drop; existing ones are never editable. Mint
 *         proceeds are pushed straight to the creator on every mint — or to a HupSplits split
 *         shared with collaborators, which the same call can create for both the mint money and
 *         the collection's resale royalties. The engine escrows nothing but its own fees.
 * @dev Collection creation code lives in per-standard deployer satellites (registered via
 *      `setDeployer`) so this engine stays under the EIP-170 size limit and a future token
 *      standard is one new satellite plus one admin transaction, never an engine redeploy. The
 *      engine is the sole mint authority on the collections it deploys; everything else about a
 *      collection (metadata, royalties, ownership) belongs to its creator from the first block.
 *      Uses IHupDrops for shared structs, events, errors, and view signatures, and integrates
 *      with Hup Core via IHup only to resolve burner session keys to primary wallets — so
 *      per-wallet limits count against the primary and cannot be reset by rotating burners.
 *      Supports rotatable ERC2771 trusted forwarders for meta-transactions, AccessControl for
 *      admin permissions, Pausable for emergency controls, and ReentrancyGuard for protected
 *      settlement. Every state change emits an event; offchain indexers derive full drop state
 *      from DropCreated / PhaseConfigured / PhasePausedSet / Minted / DropClosed /
 *      AllowlistUpdated / PayoutDestinationUpdated / DropFeatured alone.
 * @custom:version 1.0.0
 * @custom:chain multichain
 * @custom:website https://hup.social
 * @custom:security-contact security@hup.social
 * @custom:emoji 💧
 */
contract HupDrops is IHupDrops, Pausable, ReentrancyGuard, AccessControl, ERC2771Context {
  using EnumerableSet for EnumerableSet.AddressSet;
  using SafeERC20 for IERC20;

  // --- STATE VARIABLES ---

  bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
  uint256 public constant FEE_DENOMINATOR = 10_000;
  uint256 public constant ABSOLUTE_MAX_MINT_FEE_BPS = 1_000;
  uint256 public constant MAX_REFERRAL_BPS = 5_000;
  uint256 public constant MAX_PHASES = 8;

  /// @notice Longest a phase's label may be, in bytes. Counted in bytes rather than characters
  ///         because that is what storage costs: 31 bytes is one slot, and this allows two. A
  ///         non-Latin script spends 2-4 bytes per character, so the practical limit is shorter
  ///         for some creators than others — the cap is on cost, not on alphabet.
  uint256 public constant MAX_PHASE_NAME_BYTES = 64;
  uint256 public constant MAX_PER_TX = 100;

  /// @notice Hard cap on setAllowlistedBatch's array length, so a creator can't submit a batch
  ///         large enough to exceed the block gas limit and revert with nothing written.
  uint256 public constant MAX_BATCH_SIZE = 100;

  /// @notice The Hup Core contract instance (burner session resolution only). Admin-rotatable
  ///         so a Hup Core redeploy doesn't strand live drops behind a stale session source.
  IHup public hupContract;

  /// @notice The chain's LSP26 follower system, read by the Followers gate. address(0) on a
  ///         chain without one — creating a Followers-gated phase there reverts instead of
  ///         silently gating nobody.
  address public followerSystem;

  /// @notice The chain's HupCommunity registry, read by the Community gate. address(0) on a
  ///         chain without one — creating a Community-gated phase there reverts instead of
  ///         silently gating nobody. Admin-rotatable, like the follower system.
  address public communitySystem;

  /// @notice The chain's HupSplits factory, used to turn a creator's payee table into the one
  ///         address a drop pays. address(0) on a chain without one — asking for a split there
  ///         reverts rather than quietly paying a single wallet instead.
  IHupSplits public splits;

  /// @notice Total number of drops ever created; ids are 1..dropCount
  uint256 public dropCount;

  /// @notice Maps dropId to its drop
  mapping(uint256 => Drop) private _drops;

  /// @notice Maps dropId to its phase schedule, fixed at creation
  mapping(uint256 => Phase[]) private _phases;

  /// @notice Maps a standard id to its deployer satellite (address(0) = unavailable here)
  mapping(uint256 => address) public deployers;

  /// @notice Maps a deployed collection back to its drop id
  mapping(address => uint256) public dropIdOf;

  /// @notice dropId => phaseIndex => resolved primary wallet => items minted
  mapping(uint256 => mapping(uint256 => mapping(address => uint256))) public mintedInPhaseBy;

  /// @notice dropId => wallet => passes the drop's Allowlist gate. Stored onchain like
  ///         HupCommunity's whitelist — a drop is a long-lived object, so its list is worth its
  ///         SSTOREs, unlike a poll's (HupPolls keeps the merkle design for exactly that reason).
  mapping(uint256 => mapping(address => bool)) public allowlist;

  /// @dev `allowlist` mirrored into an EnumerableSet purely so the contract itself can answer
  ///      "list the allowlist" (allowlistCount/allowlistOf) — no indexer required for
  ///      correctness. cidex still indexes AllowlistUpdated for a faster/richer read path.
  mapping(uint256 => EnumerableSet.AddressSet) private _allowlistSet;

  /// @notice dropId => where the creator's share of mint proceeds is sent. address(0) (the
  ///         default) means the creator. Pushed straight from mint() like HupCommunity's
  ///         join fees — the engine never holds it — so a destination that can't receive
  ///         native coin makes mints revert until the creator re-points it. Self-inflicted
  ///         and fixable in one tx, which is why no escrow/claim ledger is needed.
  ///         Only the creator's own address can move this — see `_requireDirectCreator`.
  mapping(uint256 => address) public payoutDestination;

  mapping(address => bool) public trustedForwarders;

  /// @notice Platform share of paid mints, in basis points (100 = 1%)
  uint256 public mintFeeBps = 0;

  /// @notice Flat native fee charged per item minted, on top of the phase price and paid by the
  ///         minter. Deliberately not a share of the price: a basis-point cut earns nothing on a
  ///         free drop, which is the format most of this launchpad's supply ships in. Charged on
  ///         every mint — free, native-priced, and token-priced alike — and always in the chain's
  ///         native coin, so it lands in the same balance `withdraw` already drains.
  uint256 public mintFee = 0;

  /// @notice Whether `mintFee` is actually charged. Separate from the amount so an admin can
  ///         switch the fee off without losing a configured figure, and back on without having to
  ///         re-derive it from the chain's coin price.
  bool public mintFeeEnabled = false;

  /// @notice Flat native fee charged by createDrop
  uint256 public creationFee = 0;

  /// @notice Surcharge (in native wei) for the featured tier — paid at creation or via
  ///         `featureDrop`. Stays in the contract with the other fees; mint proceeds never touch it.
  uint256 public featuredFee = 0;

  // --- MODIFIERS ---

  modifier onlyDirectAdmin() {
    if (!hasRole(ADMIN_ROLE, msg.sender)) revert Unauthorized();
    _;
  }

  // --- CONSTRUCTOR ---

  /**
   * @notice Initializes the drops engine.
   * @param _hupAddress Address of the deployed core Hup contract.
   * @param _trustedForwarder Address of the initial EIP-2771 trusted forwarder (or address(0) to skip).
   * @param _admin Address granted DEFAULT_ADMIN_ROLE and ADMIN_ROLE.
   * @param _followerSystem The chain's LSP26 follower system (or address(0) when it has none).
   */
  constructor(address _hupAddress, address _trustedForwarder, address _admin, address _followerSystem) ERC2771Context(_trustedForwarder) {
    if (_hupAddress == address(0) || _admin == address(0)) revert InvalidAddress();

    hupContract = IHup(_hupAddress);
    followerSystem = _followerSystem;

    _grantRole(DEFAULT_ADMIN_ROLE, _admin);
    _grantRole(ADMIN_ROLE, _admin);

    if (_trustedForwarder != address(0)) {
      trustedForwarders[_trustedForwarder] = true;
      emit TrustedForwarderUpdated(_trustedForwarder, true);
    }
  }

  // --- MUTATIVE LOGIC ---

  function createDrop(
    address _creator,
    uint256 _standardId,
    bytes calldata _collectionParams,
    uint256 _maxSupply,
    uint256 _referralBps,
    bool _featured,
    PhaseInput[] calldata _phaseInputs,
    SplitsInput calldata _splits
  ) external payable whenNotPaused nonReentrant returns (uint256 dropId, address collection) {
    address deployer = deployers[_standardId];
    if (deployer == address(0)) revert InvalidStandard();
    if (_referralBps > MAX_REFERRAL_BPS) revert InvalidReferralBps();
    if (_phaseInputs.length == 0 || _phaseInputs.length > MAX_PHASES) revert InvalidPhases();

    // The featured surcharge rides on top of the creation fee rather than replacing it
    uint256 due = creationFee + (_featured ? featuredFee : 0);
    if (msg.value != due) revert InsufficientPayment(msg.value, due);

    address creator = _resolveActor(_creator);

    dropId = ++dropCount;

    // The satellite news the collection with the creator as owner and this engine as the only
    // mint authority. Reverts bubble up, so a bad params blob can never half-create a drop.
    collection = IHupDropsDeployer(deployer).deploy(creator, _maxSupply, _collectionParams);
    if (collection == address(0)) revert InvalidAddress();

    _drops[dropId] = Drop({
      collection: collection,
      creator: creator,
      standardId: _standardId,
      maxSupply: _maxSupply,
      minted: 0,
      referralBps: _referralBps,
      createdAt: uint64(block.timestamp),
      closed: false,
      featured: _featured
    });
    dropIdOf[collection] = dropId;

    emit DropCreated(dropId, creator, collection, _standardId, _maxSupply, _referralBps);

    // Emitted after DropCreated so a log-order indexer sees the drop before its flag
    if (_featured) emit DropFeatured(dropId, featuredFee);

    _configureSplits(dropId, collection, _splits);

    for (uint256 i = 0; i < _phaseInputs.length; i++) {
      _appendPhase(dropId, _maxSupply, _phaseInputs[i]);
    }
  }

  function addPhase(uint256 _dropId, PhaseInput calldata _phase) external whenNotPaused returns (uint256 phaseIndex) {
    _requireDropCreator(_dropId);
    if (_phases[_dropId].length >= MAX_PHASES) revert InvalidPhases();

    return _appendPhase(_dropId, _drops[_dropId].maxSupply, _phase);
  }

  function addPhaseBatch(uint256 _dropId, PhaseInput[] calldata _phaseInputs) external whenNotPaused returns (uint256 firstPhaseIndex) {
    _requireDropCreator(_dropId);
    if (_phaseInputs.length == 0 || _phases[_dropId].length + _phaseInputs.length > MAX_PHASES) revert InvalidPhases();

    uint256 maxSupply = _drops[_dropId].maxSupply;
    firstPhaseIndex = _phases[_dropId].length;

    for (uint256 i = 0; i < _phaseInputs.length; i++) {
      _appendPhase(_dropId, maxSupply, _phaseInputs[i]);
    }
  }

  function mint(
    address _minter,
    uint256 _dropId,
    uint256 _phaseIndex,
    uint256 _quantity,
    address _referral
  ) external payable whenNotPaused nonReentrant {
    Drop storage drop = _drops[_dropId];
    if (drop.collection == address(0)) revert DropNotFound();
    if (drop.closed) revert DropNotActive();
    if (_phaseIndex >= _phases[_dropId].length) revert PhaseNotFound();
    if (_quantity == 0 || _quantity > MAX_PER_TX) revert InvalidAmount();

    Phase storage phase = _phases[_dropId][_phaseIndex];
    if (phase.paused) revert PhaseNotActive();
    if (block.timestamp < phase.startTime || (phase.endTime != 0 && block.timestamp >= phase.endTime)) revert PhaseNotActive();

    address minter = _resolveActor(_minter);
    address creator = drop.creator;

    if (_referral != address(0)) {
      // A referral is only meaningful when the drop pays one, and never to the parties already
      // in the trade.
      if (drop.referralBps == 0 || _referral == minter || _referral == creator) revert InvalidReferral();
    }

    if (drop.maxSupply != 0 && drop.minted + _quantity > drop.maxSupply) revert SupplyExceeded(_quantity, drop.maxSupply - drop.minted);
    if (phase.allocation != 0 && phase.minted + _quantity > phase.allocation) revert AllocationExceeded(_quantity, phase.allocation - phase.minted);

    if (phase.perWallet != 0) {
      uint256 already = mintedInPhaseBy[_dropId][_phaseIndex][minter];
      if (already + _quantity > phase.perWallet) revert WalletLimitReached(phase.perWallet);
    }

    _checkGate(_dropId, phase, creator, minter);

    uint256 totalPaid = phase.price * _quantity;
    // The flat fee rides on top of the price rather than coming out of it, so the creator's take
    // is unchanged by it and a "free" phase stays free from the creator's side. Always native,
    // even on a token phase — pricing a platform fee in whatever ERC20 the creator picked would
    // leave the engine holding dust in arbitrary tokens.
    uint256 flatFee = mintFeeEnabled ? mintFee * _quantity : 0;
    // Native phases are paid with the transaction; token phases are pulled from the minter in
    // settlement, so the only value a token phase may carry is the flat fee — anything else
    // would strand in the engine.
    if (phase.token == address(0)) {
      uint256 required = totalPaid + flatFee;
      if (msg.value != required) revert InsufficientPayment(msg.value, required);
    } else if (msg.value != flatFee) {
      revert InsufficientPayment(msg.value, flatFee);
    }

    // Effects before interactions: every counter moves before any native transfer or the
    // collection's LSP1/receiver hooks can re-enter.
    uint256 firstTokenId = drop.minted + 1;
    drop.minted += _quantity;
    phase.minted += _quantity;
    mintedInPhaseBy[_dropId][_phaseIndex][minter] += _quantity;

    (uint256 priceFee, uint256 referralAmount) = _settleMint(_dropId, phase, creator, minter, _referral, drop.referralBps, totalPaid);

    // The flat fee needs no settlement of its own: it arrived as value and simply stays here,
    // waiting for withdraw, which is why it also works on a free mint that skips settlement
    // entirely. Reported folded into feeAmount so the event still carries the platform's total
    // take on the mint and its signature is unchanged for indexers.
    uint256 feeAmount = priceFee + flatFee;

    // Deliver last, once payment has fully settled.
    IHupDropCollection(drop.collection).engineMint(minter, firstTokenId, _quantity);

    emit Minted(_dropId, minter, _referral, _phaseIndex, _quantity, firstTokenId, totalPaid, feeAmount, referralAmount, drop.minted);
  }

  function setPhasePaused(uint256 _dropId, uint256 _phaseIndex, bool _paused) external whenNotPaused {
    _requireDropCreator(_dropId);
    if (_phaseIndex >= _phases[_dropId].length) revert PhaseNotFound();

    _phases[_dropId][_phaseIndex].paused = _paused;

    emit PhasePausedSet(_dropId, _phaseIndex, _paused);
  }

  function setAllowlisted(uint256 _dropId, address _wallet, bool _allowed) external whenNotPaused {
    _requireDropCreator(_dropId);

    _setAllowlistedOne(_dropId, _wallet, _allowed);
  }

  function setAllowlistedBatch(uint256 _dropId, address[] calldata _wallets, bool _allowed) external whenNotPaused {
    if (_wallets.length > MAX_BATCH_SIZE) revert BatchTooLarge();

    _requireDropCreator(_dropId);

    for (uint256 i = 0; i < _wallets.length; i++) {
      _setAllowlistedOne(_dropId, _wallets[i], _allowed);
    }
  }

  function setPayoutDestination(uint256 _dropId, address _destination) external whenNotPaused {
    _requireDirectCreator(_dropId);

    payoutDestination[_dropId] = _destination;

    emit PayoutDestinationUpdated(_dropId, _destination);
  }

  function setPayoutSplit(uint256 _dropId, IHupSplits.Payee[] calldata _payees) external whenNotPaused returns (address split) {
    _requireDirectCreator(_dropId);

    split = _requireSplits().create(_payees);
    payoutDestination[_dropId] = split;

    emit PayoutDestinationUpdated(_dropId, split);
  }

  function featureDrop(address _creator, uint256 _dropId) external payable whenNotPaused {
    Drop storage drop = _drops[_dropId];
    if (drop.creator == address(0)) revert DropNotFound();
    // A closed drop is filtered out of every featured surface, so the fee would buy nothing
    if (drop.closed) revert DropNotActive();
    if (drop.featured) revert AlreadyFeatured();
    if (_resolveActor(_creator) != drop.creator) revert Unauthorized();
    if (msg.value != featuredFee) revert InsufficientPayment(msg.value, featuredFee);

    drop.featured = true;

    emit DropFeatured(_dropId, msg.value);
  }

  function closeDrop(uint256 _dropId) external whenNotPaused {
    Drop storage drop = _drops[_dropId];
    if (drop.collection == address(0)) revert DropNotFound();
    if (drop.closed) revert DropNotActive();

    // Creator first (accepting their active burner session), then moderation. The admin check
    // is on msg.sender deliberately, matching the direct-admin convention everywhere else.
    bool byAdmin;
    if (hasRole(ADMIN_ROLE, msg.sender)) {
      byAdmin = msg.sender != drop.creator;
    } else {
      // _resolveActor reverts unless the caller is the creator or their active burner session.
      if (_resolveActor(drop.creator) != drop.creator) revert Unauthorized();
    }

    drop.closed = true;

    emit DropClosed(_dropId, byAdmin);
  }

  // --- VIEW FUNCTIONS ---

  function version() external pure override returns (string memory) {
    return "1.0.0";
  }

  function getDrop(uint256 _dropId) external view returns (Drop memory) {
    return _drops[_dropId];
  }

  function phasesOf(uint256 _dropId) external view returns (Phase[] memory) {
    return _phases[_dropId];
  }

  function activePhaseOf(uint256 _dropId) public view returns (bool found, uint256 index) {
    Phase[] storage phases = _phases[_dropId];

    for (uint256 i = 0; i < phases.length; i++) {
      if (phases[i].paused) continue;

      if (block.timestamp >= phases[i].startTime && (phases[i].endTime == 0 || block.timestamp < phases[i].endTime)) {
        return (true, i);
      }
    }

    return (false, 0);
  }

  function isMintable(uint256 _dropId, uint256 _phaseIndex, address _wallet, uint256 _quantity) external view returns (bool) {
    Drop storage drop = _drops[_dropId];
    if (drop.collection == address(0) || drop.closed || paused()) return false;
    if (_phaseIndex >= _phases[_dropId].length) return false;
    if (_quantity == 0 || _quantity > MAX_PER_TX) return false;

    Phase storage phase = _phases[_dropId][_phaseIndex];
    if (phase.paused) return false;
    if (block.timestamp < phase.startTime || (phase.endTime != 0 && block.timestamp >= phase.endTime)) return false;
    if (drop.maxSupply != 0 && drop.minted + _quantity > drop.maxSupply) return false;
    if (phase.allocation != 0 && phase.minted + _quantity > phase.allocation) return false;
    if (phase.perWallet != 0 && mintedInPhaseBy[_dropId][_phaseIndex][_wallet] + _quantity > phase.perWallet) return false;

    // Every check mint itself makes — what this returns, mint accepts.
    if (phase.gate == GateType.Allowlist) {
      return allowlist[_dropId][_wallet];
    }
    if (phase.gate == GateType.Followers) {
      // Same fallback as _checkGate — the comment above promises these two never disagree
      return ILSP26Minimal(followerSystem).isFollowing(_wallet, phase.gateAsset == address(0) ? drop.creator : phase.gateAsset);
    }
    if (phase.gate == GateType.Community) {
      return _passesCommunityGate(phase.gateData, _wallet);
    }
    if (phase.gate == GateType.AssetHolders) {
      return IGateBalance(phase.gateAsset).balanceOf(_wallet) >= phase.gateMin;
    }
    if (phase.gate == GateType.AssetHolders1155) {
      return IGateBalance1155(phase.gateAsset).balanceOf(_wallet, uint256(phase.gateData)) >= phase.gateMin;
    }

    return true;
  }

  function allowlistCount(uint256 _dropId) external view returns (uint256) {
    _requireCreatorView(_dropId);

    return _allowlistSet[_dropId].length();
  }

  function allowlistOf(uint256 _dropId, uint256 _offset, uint256 _limit) external view returns (address[] memory) {
    _requireCreatorView(_dropId);

    return _page(_allowlistSet[_dropId], _offset, _limit);
  }

  // --- ADMIN CONFIGURATION ---

  function pause() external onlyDirectAdmin {
    _pause();
  }

  function unpause() external onlyDirectAdmin {
    _unpause();
  }

  function setDeployer(uint256 _standardId, address _deployer) external onlyDirectAdmin {
    // address(0) is a valid value: it retires a standard on this chain without touching
    // existing drops, which keep minting through their already-deployed collections.
    deployers[_standardId] = _deployer;

    emit DeployerUpdated(_standardId, _deployer);
  }

  function setMintFeeBps(uint256 _mintFeeBps) external onlyDirectAdmin {
    if (_mintFeeBps > ABSOLUTE_MAX_MINT_FEE_BPS) revert InvalidFeeBps();

    uint256 oldValue = mintFeeBps;
    mintFeeBps = _mintFeeBps;

    emit MintFeeUpdated(oldValue, _mintFeeBps);
  }

  /**
   * @notice Sets the flat per-item native mint fee. Uncapped, like `creationFee`: a sane ceiling
   *         is a coin-price question, not a bytecode one, and it differs on every chain the
   *         engine deploys to.
   * @dev Setting it does not switch it on — `mintFeeEnabled` does, so the amount can be staged
   *      ahead of the flip.
   */
  function setMintFee(uint256 _mintFee) external onlyDirectAdmin {
    uint256 oldValue = mintFee;
    mintFee = _mintFee;

    emit FlatMintFeeUpdated(oldValue, _mintFee);
  }

  function setMintFeeEnabled(bool _enabled) external onlyDirectAdmin {
    mintFeeEnabled = _enabled;

    emit MintFeeEnabledUpdated(_enabled);
  }

  function setCreationFee(uint256 _creationFee) external onlyDirectAdmin {
    uint256 oldValue = creationFee;
    creationFee = _creationFee;

    emit CreationFeeUpdated(oldValue, _creationFee);
  }

  function setFeaturedFee(uint256 _featuredFee) external onlyDirectAdmin {
    uint256 oldValue = featuredFee;
    featuredFee = _featuredFee;

    emit FeaturedFeeUpdated(oldValue, _featuredFee);
  }

  function setFollowerSystem(address _followerSystem) external onlyDirectAdmin {
    address oldValue = followerSystem;
    followerSystem = _followerSystem;

    emit FollowerSystemUpdated(oldValue, _followerSystem);
  }

  function setCommunitySystem(address _communitySystem) external onlyDirectAdmin {
    address oldValue = communitySystem;
    communitySystem = _communitySystem;

    emit CommunitySystemUpdated(oldValue, _communitySystem);
  }

  function setSplits(address _splits) external onlyDirectAdmin {
    address oldValue = address(splits);
    splits = IHupSplits(_splits);

    emit SplitsUpdated(oldValue, _splits);
  }

  function setTrustedForwarder(address _forwarder, bool _trusted) external onlyDirectAdmin {
    if (_forwarder == address(0)) revert InvalidAddress();

    trustedForwarders[_forwarder] = _trusted;

    emit TrustedForwarderUpdated(_forwarder, _trusted);
  }

  function setHupContract(address _hupAddress) external onlyDirectAdmin {
    if (_hupAddress == address(0)) revert InvalidAddress();

    address oldValue = address(hupContract);
    hupContract = IHup(_hupAddress);

    emit HupContractUpdated(oldValue, _hupAddress);
  }

  function withdrawAll(address payable _receiver) external onlyDirectAdmin nonReentrant {
    if (_receiver == address(0)) revert InvalidAddress();

    uint256 balance = address(this).balance;
    if (balance == 0) revert TransferFailed();

    (bool success, ) = _receiver.call{value: balance}("");
    if (!success) revert TransferFailed();

    emit Withdrawal(_receiver, balance);
  }

  function withdrawToken(address _token, address _receiver, bool _isLsp7) external onlyDirectAdmin nonReentrant {
    if (_token == address(0) || _receiver == address(0)) revert InvalidAddress();

    uint256 balance = IERC20(_token).balanceOf(address(this));
    if (balance == 0) revert TransferFailed();

    // balanceOf is selector-compatible across ERC20 and LSP7; the transfers are not.
    if (_isLsp7) {
      ILSP7Minimal(_token).transfer(address(this), _receiver, balance, true, "");
    } else {
      IERC20(_token).safeTransfer(_receiver, balance);
    }

    emit Withdrawal(_receiver, balance);
  }

  // --- ROLE MANAGEMENT ---

  function grantRole(bytes32 role, address account) public override {
    if (!hasRole(getRoleAdmin(role), msg.sender)) revert Unauthorized();

    _grantRole(role, account);
  }

  function revokeRole(bytes32 role, address account) public override {
    if (!hasRole(getRoleAdmin(role), msg.sender)) revert Unauthorized();

    _revokeRole(role, account);
  }

  function renounceRole(bytes32 role, address callerConfirmation) public override {
    if (callerConfirmation != msg.sender) revert Unauthorized();

    _revokeRole(role, callerConfirmation);
  }

  // --- INTERNAL & OVERRIDE HELPERS ---

  /**
   * @dev The shared gate in front of every creator-only lever (phase pause, allowlist edits):
   *      the drop must exist and still be open, and the caller must be its creator or their
   *      active burner session. Admins deliberately have no say here — moderation's levers are
   *      closeDrop and the engine-wide pause, while a sale's own controls belong to whoever is
   *      running it.
   */
  function _requireDropCreator(uint256 _dropId) internal view {
    Drop storage drop = _drops[_dropId];
    if (drop.collection == address(0)) revert DropNotFound();
    if (drop.closed) revert DropNotActive();

    if (_resolveActor(drop.creator) != drop.creator) revert Unauthorized();
  }

  /**
   * @dev The payout lever's gate, deliberately stricter than _requireDropCreator: the caller must
   *      be the creator's own address — not a burner session, not a forwarder relay. Both of those
   *      resolve identity through admin-rotatable references (`hupContract` for sessions,
   *      `trustedForwarders` for relays), so honouring them here would mean a compromised admin
   *      key could point another creator's revenue at itself by swapping in a session source or a
   *      forwarder that vouches for anyone. Redirecting money is worth one direct signature — the
   *      same reasoning that keeps `onlyDirectAdmin` on `msg.sender`.
   */
  function _requireDirectCreator(uint256 _dropId) private view {
    Drop storage drop = _drops[_dropId];
    if (drop.collection == address(0)) revert DropNotFound();
    if (drop.closed) revert DropNotActive();

    if (msg.sender != drop.creator) revert Unauthorized();
  }

  /**
   * @dev The listing views' gate: creator (or their burner session) only, like HupCommunity's
   *      whitelist views — but without the closed check, since the list outlives the sale.
   *      Everyone else answers "is X on it" through the public `allowlist` getter.
   */
  function _requireCreatorView(uint256 _dropId) private view {
    Drop storage drop = _drops[_dropId];
    if (drop.collection == address(0)) revert DropNotFound();

    if (_resolveActor(drop.creator) != drop.creator) revert Unauthorized();
  }

  /// @dev HupCommunity's pagination routine: clamps against the remaining tail rather than
  ///      truncating offset + limit afterwards — the sum overflows to a panic revert on a
  ///      caller passing an unbounded `limit`.
  function _page(EnumerableSet.AddressSet storage _set, uint256 _offset, uint256 _limit) private view returns (address[] memory page) {
    uint256 total = _set.length();
    if (_offset >= total || _limit == 0) return new address[](0);

    uint256 remaining = total - _offset;
    uint256 end = _offset + (_limit < remaining ? _limit : remaining);

    page = new address[](end - _offset);
    for (uint256 i = _offset; i < end; i++) {
      page[i - _offset] = _set.at(i);
    }
  }

  /**
   * @dev Validates one phase and pushes it onto a drop's schedule, emitting PhaseConfigured
   *      with the index it landed at. Shared by createDrop and addPhase so an appended phase
   *      can never be held to looser rules than one declared at creation, and so indexers see
   *      an identical event either way.
   */
  function _appendPhase(uint256 _dropId, uint256 _maxSupply, PhaseInput calldata _phase) private returns (uint256 phaseIndex) {
    if (bytes(_phase.name).length > MAX_PHASE_NAME_BYTES) revert PhaseNameTooLong();
    if (_phase.endTime != 0 && _phase.endTime <= _phase.startTime) revert InvalidPhases();
    if (_maxSupply != 0 && _phase.allocation > _maxSupply) revert InvalidPhases();
    // A free phase has nothing to charge in, so naming a token there is a mistake worth
    // catching rather than storing — it would read as a priced phase to every client.
    if (_phase.price == 0 && _phase.token != address(0)) revert InvalidPaymentToken();
    _validateGate(_phase.gate, _phase.gateAsset, _phase.gateData, _phase.gateMin);

    phaseIndex = _phases[_dropId].length;

    _phases[_dropId].push(Phase({
      name: _phase.name,
      startTime: _phase.startTime,
      endTime: _phase.endTime,
      paused: _phase.paused,
      token: _phase.token,
      isLsp7: _phase.isLsp7,
      price: _phase.price,
      perWallet: _phase.perWallet,
      allocation: _phase.allocation,
      gate: _phase.gate,
      gateAsset: _phase.gateAsset,
      gateData: _phase.gateData,
      gateMin: _phase.gateMin,
      minted: 0
    }));

    emit PhaseConfigured(
      _dropId,
      phaseIndex,
      _phase.startTime,
      _phase.endTime,
      _phase.price,
      _phase.perWallet,
      _phase.allocation,
      _phase.gate,
      _phase.gateAsset,
      _phase.gateData,
      _phase.gateMin,
      _phase.paused,
      _phase.token,
      _phase.isLsp7,
      _phase.name
    );
  }

  /**
   * @dev One allowlist entry flipped, mapping and enumerable mirror together — HupCommunity's
   *      _setWhitelistedOne, drop-scoped.
   */
  function _setAllowlistedOne(uint256 _dropId, address _wallet, bool _allowed) private {
    allowlist[_dropId][_wallet] = _allowed;

    if (_allowed) {
      _allowlistSet[_dropId].add(_wallet);
    } else {
      _allowlistSet[_dropId].remove(_wallet);
    }

    emit AllowlistUpdated(_dropId, _wallet, _allowed);
  }

  /**
   * @dev Rejects gate configurations that could never pass or would silently gate nobody.
   *      Allowlist needs none — its list lives in `allowlist` and may be filled before or
   *      after the phase opens.
   */
  function _validateGate(GateType _gate, address _gateAsset, bytes32 _gateData, uint256 _gateMin) internal view {
    if (_gate == GateType.Open || _gate == GateType.Allowlist) return;

    if (_gate == GateType.Followers) {
      if (followerSystem == address(0)) revert InvalidGateConfig();
    } else if (_gate == GateType.Community) {
      // Community id 0 is never a real community, so it would gate everyone out silently
      if (communitySystem == address(0) || _gateData == bytes32(0)) revert InvalidGateConfig();
    } else {
      // AssetHolders / AssetHolders1155
      if (_gateAsset == address(0) || _gateMin == 0) revert InvalidGateConfig();
    }
  }

  /**
   * @dev Membership of the community `_gateData` names. A banned wallet is excluded even where
   *      the registry still records it as a member — a ban is the community saying no, and a
   *      gate that ignored it would hand banned wallets the mint anyway.
   */
  function _passesCommunityGate(bytes32 _gateData, address _minter) internal view returns (bool) {
    (bool isMember, , , bool isBanned, ) = IHupCommunityMinimal(communitySystem).registry(uint256(_gateData), _minter);

    return isMember && !isBanned;
  }

  /**
   * @dev Reverts with GateNotPassed unless `_minter` passes the phase's gate.
   */
  function _checkGate(uint256 _dropId, Phase storage _phase, address _creator, address _minter) internal view {
    GateType gate = _phase.gate;

    if (gate == GateType.Open) return;

    if (gate == GateType.Allowlist) {
      if (!allowlist[_dropId][_minter]) revert GateNotPassed();
    } else if (gate == GateType.Followers) {
      // Unset means the creator, so a drop that never names an account behaves exactly as before
      address followed = _phase.gateAsset == address(0) ? _creator : _phase.gateAsset;
      if (!ILSP26Minimal(followerSystem).isFollowing(_minter, followed)) revert GateNotPassed();
    } else if (gate == GateType.Community) {
      if (!_passesCommunityGate(_phase.gateData, _minter)) revert GateNotPassed();
    } else if (gate == GateType.AssetHolders) {
      if (IGateBalance(_phase.gateAsset).balanceOf(_minter) < _phase.gateMin) revert GateNotPassed();
    } else {
      if (IGateBalance1155(_phase.gateAsset).balanceOf(_minter, uint256(_phase.gateData)) < _phase.gateMin) revert GateNotPassed();
    }
  }

  /**
   * @dev Deploys the creator's payee tables through the HupSplits factory, so a drop's shares
   *      are onchain from its first block. The royalty split is only checked, not applied: the
   *      collection took its ERC2981 receiver from the params blob, which is opaque here, so the
   *      caller predicts the split's (deterministic) address and encodes it there. A collection
   *      that ended up pointing somewhere else would pay the wrong people on every resale, which
   *      is worth failing the whole drop over.
   */
  function _configureSplits(uint256 _dropId, address _collection, SplitsInput calldata _splits) private {
    if (_splits.royalty.length > 0) {
      address royaltySplit = _requireSplits().create(_splits.royalty);
      (address receiver, ) = IERC2981Minimal(_collection).royaltyInfo(0, FEE_DENOMINATOR);

      if (receiver != royaltySplit) revert SplitMismatch(royaltySplit, receiver);
    }

    address destination = _splits.payoutDestination;
    if (_splits.payout.length > 0) destination = _requireSplits().create(_splits.payout);

    if (destination != address(0)) {
      payoutDestination[_dropId] = destination;

      emit PayoutDestinationUpdated(_dropId, destination);
    }
  }

  /**
   * @dev The splits factory, or a revert naming why a split cannot be made on this chain.
   */
  function _requireSplits() private view returns (IHupSplits) {
    if (address(splits) == address(0)) revert SplitsUnavailable();

    return splits;
  }

  /**
   * @dev Splits a paid mint: the platform fee stays in the contract, the referral share goes to
   *      the referrer, and the remainder is pushed straight to the drop's payout destination —
   *      the creator unless they re-pointed it. Direct push, one address, resolved now: rules
   *      richer than "one wallet" live in the destination contract, not here. Free mints skip
   *      settlement entirely.
   */
  function _settleMint(
    uint256 _dropId,
    Phase storage _phase,
    address _creator,
    address _minter,
    address _referral,
    uint256 _referralBps,
    uint256 _totalPaid
  ) internal returns (uint256 feeAmount, uint256 referralAmount) {
    if (_totalPaid == 0) return (0, 0);

    feeAmount = (_totalPaid * mintFeeBps) / FEE_DENOMINATOR;
    referralAmount = _referral == address(0) ? 0 : (_totalPaid * _referralBps) / FEE_DENOMINATOR;

    address recipient = payoutDestination[_dropId];
    if (recipient == address(0)) recipient = _creator;

    uint256 creatorAmount = _totalPaid - feeAmount - referralAmount;

    if (_phase.token == address(0)) {
      _sendNative(recipient, creatorAmount);
      if (referralAmount > 0) _sendNative(_referral, referralAmount);
      return (feeAmount, referralAmount);
    }

    // Token phases move value straight from the minter to each party, so the engine never
    // custodies the creator's or referrer's share — only its own fee lands here, waiting for
    // withdrawToken. The minter must have approved (ERC20) or authorized this engine as an
    // operator (LSP7) for the full total beforehand.
    _pullToken(_phase, _minter, recipient, creatorAmount);
    if (referralAmount > 0) _pullToken(_phase, _minter, _referral, referralAmount);
    if (feeAmount > 0) _pullToken(_phase, _minter, address(this), feeAmount);
  }

  /**
   * @dev One token transfer out of the minter's balance. LSP7 has no `transferFrom` and its
   *      `transfer` is not selector-compatible with ERC20's, so the two standards need
   *      different calls — the same split HupCommunity's paid joins make. `force` is true so a
   *      plain EOA or a UP without an LSP1 delegate can receive.
   */
  function _pullToken(Phase storage _phase, address _from, address _to, uint256 _amount) private {
    if (_phase.isLsp7) {
      ILSP7Minimal(_phase.token).transfer(_from, _to, _amount, true, "");
    } else {
      IERC20(_phase.token).safeTransferFrom(_from, _to, _amount);
    }
  }

  /**
   * @dev Sends native value, reverting on failure.
   */
  function _sendNative(address _to, uint256 _amount) internal {
    if (_amount == 0) return;

    (bool success, ) = _to.call{value: _amount}("");
    if (!success) revert TransferFailed();
  }

  /**
   * @dev Resolves the primary owner address based on burner session rules.
   */
  function _resolveActor(address _owner) internal view returns (address) {
    address sender = _msgSender();

    if (sender == address(0)) revert InvalidAddress();

    if (_owner == address(0) || _owner == sender) {
      return sender;
    }

    (address burnerKey, uint256 expiresAt) = hupContract.userSessions(_owner);
    if (burnerKey != sender) revert Unauthorized();
    if (block.timestamp >= expiresAt) revert SessionExpired();

    return _owner;
  }

  /**
   * @dev See EIP-2771. Returns true if the address is a trusted forwarder.
   */
  function isTrustedForwarder(address forwarder) public view override(ERC2771Context, IHupDrops) returns (bool) {
    return trustedForwarders[forwarder];
  }

  /**
   * @dev Returns the original signer of the transaction, supporting meta-transactions.
   */
  function _msgSender() internal view override(Context, ERC2771Context) returns (address) {
    return ERC2771Context._msgSender();
  }

  /**
   * @dev Returns the input call data, supporting meta-transactions.
   */
  function _msgData() internal view override(Context, ERC2771Context) returns (bytes calldata) {
    return ERC2771Context._msgData();
  }

  /**
   * @dev Returns the context suffix length, supporting meta-transactions.
   */
  function _contextSuffixLength() internal view override(Context, ERC2771Context) returns (uint256) {
    return ERC2771Context._contextSuffixLength();
  }

  receive() external payable {
    emit UnattributedDeposit(msg.sender, msg.value);
  }
}

v2/Extensions/IHupDrops.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.35;

import "./../IHup.sol";
import { IHupSplits } from "./IHupSplits.sol";

/**
 * @title IHupDrops
 * @author Hup Labs
 * @notice Shared interface for the Hup Drops protocol — the NFT launchpad. A drop deploys a real,
 *         creator-owned collection contract (LSP7/LSP8 on LUKSO, ERC721/ERC1155 elsewhere) and
 *         sells its primary mint through phases: each phase carries its own window, price,
 *         per-wallet limit, allocation, and gate (open, onchain allowlist, LSP26 followers, or
 *         asset holders).
 * @dev Completes the Hup NFT stack: HupDrops is primary issuance, HupTrade (one-of-ones) and
 *      HupEditions (balance-based) are the secondary markets — a drop-minted collection is
 *      immediately listable on the matching one. Defines the public events, custom errors,
 *      structs, and interfaces used by clients and offchain indexers, plus the two plumbing
 *      interfaces (deployer satellites, collection mint hook) the engine composes with.
 * @custom:version 1.0.0
 * @custom:chain multichain
 * @custom:website https://hup.social
 * @custom:security-contact security@hup.social
 * @custom:emoji 💧
 */
interface IHupDrops {
  // --- SHARED TYPES ---

  /// @notice Who may mint during a phase.
  /// @dev `Allowlist` checks the drop's onchain allowlist — a stored set the creator edits via
  ///      `setAllowlisted`/`setAllowlistedBatch`, the same shape as HupCommunity's whitelist, so
  ///      eligibility is one public mapping read with no offchain file or proof to carry.
  ///      `Followers` asks the chain's LSP26 follower system whether the minter follows the
  ///      drop's creator. `AssetHolders` checks `balanceOf(address)` on `gateAsset` (covers
  ///      ERC20, ERC721, LSP7, and LSP8); `AssetHolders1155` checks
  ///      `balanceOf(address, uint256(gateData))` for id-scoped ERC1155 balances. `Community`
  ///      asks the chain's HupCommunity registry whether the minter is a member of the
  ///      community whose id `gateData` carries, and is not banned from it.
  /// @dev Appended to, never reordered: the numbers are stored in every drop ever created and
  ///      indexed offchain against them.
  enum GateType {
    Open,
    Allowlist,
    Followers,
    AssetHolders,
    AssetHolders1155,
    Community
  }

  /// @notice One mint phase. A phase's terms are fixed at creation — Universal Page's "you can
  ///         not change the launch dates after deployment" rule — so a buyer's terms can never
  ///         shift under them. `paused` is the single exception: the creator's on/off switch
  ///         over their own sale, replayable by indexers from `PhasePausedSet`.
  /// @dev `endTime` 0 means open-ended. `perWallet` 0 means unlimited. `allocation` 0 means the
  ///      phase draws freely from the drop's total supply. `gateData` carries the ERC1155 token
  ///      id for `AssetHolders1155`, the community id for `Community`, and is zero otherwise.
  ///      A `paused` phase never mints, whatever its window says.
  /// @notice What a phase charges. `token` address(0) is the chain's native coin — the default
  ///         and the only one-transaction path. Anything else is an ERC20, or an LSP7 when
  ///         `isLsp7` is set: LSP7's `transfer(from,to,amount,force,data)` is not
  ///         selector-compatible with ERC20's `transferFrom`, so the two need different calls
  ///         (unlike `balanceOf`, which is why the asset gates need no such flag).
  /// @dev A token mint costs the minter an approval first — `approve` for ERC20,
  ///      `authorizeOperator` for LSP7 — so it is two transactions where native is one.
  /// @dev `name` is the creator's own label for the phase ("Presale", "Christmas Edition") —
  ///      stored onchain rather than in an indexer so `phasesOf` answers it directly and no
  ///      offchain record has to be kept in step with the schedule. Capped at
  ///      MAX_PHASE_NAME_BYTES; empty is fine and clients fall back to the index.
  struct Phase {
    string name;
    uint64 startTime;
    uint64 endTime;
    bool paused;
    address token;
    bool isLsp7;
    uint256 price;
    uint256 perWallet;
    uint256 allocation;
    GateType gate;
    address gateAsset;
    bytes32 gateData;
    uint256 gateMin;
    uint256 minted;
  }

  /// @notice Same shape as `Phase` minus the counter — what `createDrop` accepts. Creating a
  ///         phase with `paused` true is how a drop waits for the creator to press start
  ///         rather than for a clock.
  struct PhaseInput {
    string name;
    uint64 startTime;
    uint64 endTime;
    bool paused;
    address token;
    bool isLsp7;
    uint256 price;
    uint256 perWallet;
    uint256 allocation;
    GateType gate;
    address gateAsset;
    bytes32 gateData;
    uint256 gateMin;
  }

  /// @notice A drop: one collection, one creator, one phase schedule.
  /// @dev `maxSupply` 0 means an open edition. `minted` is the running total across all phases;
  ///      token ids are 1-based, so token `n` of a numbered collection is the `n`-th mint.
  ///      `closed` is final — a closed drop never mints again, though the collection contract
  ///      lives on under its creator's ownership.
  struct Drop {
    address collection;
    address creator;
    uint256 standardId;
    uint256 maxSupply;
    uint256 minted;
    uint256 referralBps;
    uint64 createdAt;
    bool closed;
    bool featured;
  }

  /// @notice Where a new drop's money goes — mint proceeds and secondary royalties.
  /// @dev A payee table becomes one split address through the HupSplits factory during
  ///      `createDrop`; an empty table means no split. `payoutDestination` is the plain
  ///      one-address form and is used only when `payout` is empty, with address(0) leaving mint
  ///      proceeds with the creator. `royalty` must resolve to the same address the collection
  ///      params named as the ERC2981 receiver, or the drop reverts.
  struct SplitsInput {
    address payoutDestination;
    IHupSplits.Payee[] payout;
    IHupSplits.Payee[] royalty;
  }

  // --- SHARED EVENTS ---

  /// @notice Emitted once per drop. Together with PhaseConfigured, PhasePausedSet, Minted,
  ///         DropClosed, AllowlistUpdated, PayoutDestinationUpdated, and DropFeatured this is
  ///         the single source of truth for offchain indexers — full drop state is derivable
  ///         from these eight events alone.
  event DropCreated(uint256 indexed dropId, address indexed creator, address indexed collection, uint256 standardId, uint256 maxSupply, uint256 referralBps);

  /// @notice Emitted once per phase — at creation in index order, and again for each phase a
  ///         creator appends later with `addPhase`, carrying its new index.
  event PhaseConfigured(uint256 indexed dropId, uint256 indexed phaseIndex, uint64 startTime, uint64 endTime, uint256 price, uint256 perWallet, uint256 allocation, GateType gate, address gateAsset, bytes32 gateData, uint256 gateMin, bool paused, address token, bool isLsp7, string name);

  /// @notice Emitted whenever a creator pauses or resumes one of their phases — including the
  ///         first start of a phase created paused.
  event PhasePausedSet(uint256 indexed dropId, uint256 indexed phaseIndex, bool paused);

  /// @notice Emitted for every mint. `firstTokenId` starts the contiguous id range this mint
  ///         produced (`quantity` ids for numbered standards; edition standards mint balance
  ///         only and clients ignore the range). `dropMinted` is the post-mint drop total, so a
  ///         progress bar needs no extra read.
  event Minted(uint256 indexed dropId, address indexed minter, address indexed referral, uint256 phaseIndex, uint256 quantity, uint256 firstTokenId, uint256 totalPaid, uint256 feeAmount, uint256 referralAmount, uint256 dropMinted);

  /// @notice Emitted when a drop is closed for good, by its creator or by moderation.
  event DropClosed(uint256 indexed dropId, bool byAdmin);

  /// @notice Emitted when a creator adds a wallet to, or removes it from, a drop's allowlist —
  ///         one event per wallet, batch or not, mirroring HupCommunity's WhitelistUpdated.
  ///         Indexers replay these for search; correctness never needs them, since the list is
  ///         enumerable onchain via `allowlistCount`/`allowlistOf`.
  event AllowlistUpdated(uint256 indexed dropId, address indexed wallet, bool allowed);

  /// @notice Emitted when a creator re-points where their share of mint proceeds is sent.
  ///         address(0) means back to the creator.
  event PayoutDestinationUpdated(uint256 indexed dropId, address indexed destination);

  /// @notice Emitted when the HupSplits factory this engine makes splits through is set or
  ///         replaced.
  event SplitsUpdated(address oldValue, address newValue);

  /// @notice Emitted when a standard's deployer satellite is registered or replaced. Registering
  ///         a new standard id is how a future token standard joins without redeploying the
  ///         engine.
  event DeployerUpdated(uint256 indexed standardId, address deployer);

  /// @notice Emitted when the platform's share of mint proceeds (basis points) is updated.
  event MintFeeUpdated(uint256 oldValue, uint256 newValue);

  /// @notice Emitted when the flat per-item native mint fee is updated. Distinct from
  ///         MintFeeUpdated: that one carries basis points, this one a native amount.
  event FlatMintFeeUpdated(uint256 oldValue, uint256 newValue);

  /// @notice Emitted when the flat per-item mint fee is switched on or off, leaving its
  ///         configured amount untouched.
  event MintFeeEnabledUpdated(bool enabled);

  /// @notice Emitted when the flat native fee charged by createDrop is updated.
  event CreationFeeUpdated(uint256 oldValue, uint256 newValue);

  /// @notice A drop bought the featured tier, at creation or later. Carries what was paid, so an
  ///         indexer never has to read the fee that happened to be set at the time.
  event DropFeatured(uint256 indexed dropId, uint256 feePaid);

  event FeaturedFeeUpdated(uint256 oldValue, uint256 newValue);

  /// @notice Emitted when the LSP26 follower system reference is rotated.
  event FollowerSystemUpdated(address oldValue, address newValue);

  /// @notice Emitted when the HupCommunity registry reference is rotated.
  event CommunitySystemUpdated(address oldValue, address newValue);

  /// @notice Emitted when a trusted forwarder's status is updated.
  event TrustedForwarderUpdated(address indexed forwarder, bool trusted);

  /// @notice Emitted when the Hup Core contract reference (burner session source) is rotated.
  event HupContractUpdated(address oldValue, address newValue);

  /// @notice Emitted when accumulated native fees are withdrawn by an admin.
  event Withdrawal(address indexed recipient, uint256 amount);

  /// @notice Emitted when the contract receives a plain, unattributed native token deposit.
  event UnattributedDeposit(address indexed from, uint256 amount);

  // --- SHARED ERRORS ---

  error InvalidAddress();
  error InvalidAmount();
  error InvalidFeeBps();
  error InvalidReferralBps();
  /// @notice No deployer satellite is registered for this standard id on this chain.
  error InvalidStandard();
  /// @notice The phase list is empty, longer than MAX_PHASES, or a phase's window is inverted.
  error InvalidPhases();
  error PhaseNameTooLong();
  /// @notice A gate is missing its required configuration (follower gate on a chain with no
  ///         follower system, community gate with no registry or a zero community id, asset
  ///         gate without asset or minimum).
  error InvalidGateConfig();
  /// @notice setAllowlistedBatch received more than MAX_BATCH_SIZE addresses.
  error BatchTooLarge();
  error DropNotFound();
  error AlreadyFeatured();
  /// @notice The drop is closed, or the engine is paused for moderation.
  error DropNotActive();
  error PhaseNotFound();
  /// @notice The phase's time window is not currently open, or its creator has paused it.
  error PhaseNotActive();
  /// @notice The minter does not pass the phase's gate (not on the allowlist, not a follower,
  ///         or balance below the gate minimum).
  error GateNotPassed();
  /// @notice This wallet has reached the phase's per-wallet limit.
  error WalletLimitReached(uint256 limit);
  /// @notice The requested quantity exceeds the phase's remaining allocation.
  error AllocationExceeded(uint256 requested, uint256 remaining);
  /// @notice The requested quantity exceeds the drop's remaining supply.
  error SupplyExceeded(uint256 requested, uint256 remaining);
  error InsufficientPayment(uint256 provided, uint256 required);
  /// @notice A token-priced phase was sent native value, or a phase priced at zero named a token.
  error InvalidPaymentToken();
  /// @notice The referrer must be neither the minter nor the creator, and referrals require the
  ///         drop to carry a referral share.
  error InvalidReferral();
  error TransferFailed();
  error Unauthorized();
  error SessionExpired();
  /// @notice A split was asked for on a chain with no HupSplits factory registered.
  error SplitsUnavailable();
  /// @notice The royalty split the engine deployed is not the ERC2981 receiver the collection
  ///         was created with — resales would have paid the wrong address.
  error SplitMismatch(address expected, address actual);

  // --- STATE GETTERS ---

  function version() external pure returns (string memory);
  function hupContract() external view returns (IHup);
  function followerSystem() external view returns (address);
  /// @notice The chain's HupCommunity registry, read by the Community gate. address(0) on a
  ///         chain without one — creating a Community-gated phase there reverts.
  function communitySystem() external view returns (address);
  /// @notice The chain's HupSplits factory. address(0) on a chain without one — asking for a
  ///         split there reverts.
  function splits() external view returns (IHupSplits);
  function ADMIN_ROLE() external view returns (bytes32);
  function trustedForwarders(address forwarder) external view returns (bool);
  function isTrustedForwarder(address forwarder) external view returns (bool);
  function mintFeeBps() external view returns (uint256);
  function mintFee() external view returns (uint256);
  function mintFeeEnabled() external view returns (bool);
  function creationFee() external view returns (uint256);

  function featuredFee() external view returns (uint256);
  function FEE_DENOMINATOR() external view returns (uint256);
  function ABSOLUTE_MAX_MINT_FEE_BPS() external view returns (uint256);
  function MAX_REFERRAL_BPS() external view returns (uint256);
  function MAX_PHASES() external view returns (uint256);
  function MAX_PER_TX() external view returns (uint256);
  function MAX_BATCH_SIZE() external view returns (uint256);
  /// @notice Total number of drops ever created; drop ids are 1..dropCount.
  function dropCount() external view returns (uint256);
  /// @notice The deployer satellite for a standard id, or address(0) when the standard is not
  ///         available on this chain. Canonical ids: 1 = ERC721, 2 = ERC1155, 3 = LSP7, 4 = LSP8;
  ///         future standards take the next free id.
  function deployers(uint256 standardId) external view returns (address);
  /// @notice Reverse lookup from a collection this engine deployed to its drop id (0 if unknown).
  function dropIdOf(address collection) external view returns (uint256);
  /// @notice How many items `wallet` minted in a phase, keyed by the resolved primary wallet.
  function mintedInPhaseBy(uint256 dropId, uint256 phaseIndex, address wallet) external view returns (uint256);
  /// @notice Whether `wallet` passes a drop's Allowlist gate — the one read a client needs to
  ///         show "you're on the list". Public deliberately: the list's members are as public
  ///         as the events that built it.
  function allowlist(uint256 dropId, address wallet) external view returns (bool);
  /// @notice Where a drop's share of mint proceeds is pushed. address(0) (the default) means
  ///         the creator; anything else is an explicit override — a co-founder split, a DAO
  ///         treasury, or a splitter contract enforcing whatever rules it likes.
  function payoutDestination(uint256 dropId) external view returns (address);

  // --- MUTATIVE LOGIC ---

  /**
   * @notice Creates a drop: deploys the collection through the standard's registered deployer
   *         satellite and stores its phase schedule. The collection is owned by the creator from
   *         its first block; this engine only ever holds mint authority.
   * @dev msg.value must equal `creationFee` plus `featuredFee` when `_featured`, exactly. Phases
   *      are validated and then immutable.
   * @param _creator The primary wallet creating the drop (or address(0) if caller is primary).
   * @param _standardId Which registered standard to deploy (see `deployers`).
   * @param _collectionParams ABI-encoded constructor parameters, decoded by the standard's
   *        deployer satellite (name, symbol, metadata, royalties — shape is per standard).
   * @param _maxSupply Total mintable items, fixed forever. 0 = open edition.
   * @param _referralBps Share of each paid mint (basis points) paid to the mint-time referrer.
   * @param _featured Buy the featured tier now, for `featuredFee` on top of the creation fee.
   *        `featureDrop` does the same thing later, at the fee set then.
   * @param _phases The phase schedule, in order. 1..MAX_PHASES entries.
   * @param _splits Where the money goes. Either payee table is deployed through the HupSplits
   *        factory here; `royalty` must match the ERC2981 receiver encoded in
   *        `_collectionParams`, which the caller predicts from the same table.
   * @return dropId The id of the created drop.
   * @return collection The deployed collection contract.
   */
  function createDrop(address _creator, uint256 _standardId, bytes calldata _collectionParams, uint256 _maxSupply, uint256 _referralBps, bool _featured, PhaseInput[] calldata _phases, SplitsInput calldata _splits) external payable returns (uint256 dropId, address collection);

  /**
   * @notice Buys the featured tier for an existing drop. Only the drop's creator may do it, only
   *         while the drop is open, and only once — the fee is not a subscription, and a second
   *         payment would be silently lost.
   * @dev msg.value must equal `featuredFee` exactly.
   * @param _creator The primary wallet (or address(0) if caller is primary).
   * @param _dropId The drop to feature.
   */
  function featureDrop(address _creator, uint256 _dropId) external payable;

  /// @notice Sets the featured surcharge. Uncapped, like `creationFee`.
  function setFeaturedFee(uint256 _featuredFee) external;

  /**
   * @notice Mints `_quantity` items from a drop's phase. msg.value must exactly equal the phase
   *         price times the quantity. The platform fee stays in the contract; the referral share
   *         goes to `_referral` when provided; the remainder is pushed straight to the creator —
   *         no escrow.
   * @param _minter The primary wallet minting (or address(0) if caller is primary). Per-wallet
   *        limits count against the resolved primary, so a burner session cannot reset them.
   * @param _dropId The drop to mint from.
   * @param _phaseIndex Which phase to mint through; its window must be open.
   * @param _quantity How many items. 1..MAX_PER_TX.
   * @param _referral The referrer credited with the mint, or address(0) for none. Must be
   *        neither minter nor creator.
   */
  function mint(address _minter, uint256 _dropId, uint256 _phaseIndex, uint256 _quantity, address _referral) external payable;

  /**
   * @notice Pauses or resumes one phase, any number of times in either direction. Callable by
   *         the drop's creator (or their active burner session) only — pausing is a creator's
   *         lever over their own sale, not a moderation tool; moderation closes the drop or
   *         pauses the engine instead.
   * @dev Nothing else about the phase can change: window, price, limits, and gate stay
   *       immutable. A paused phase reverts `PhaseNotActive` on mint and is skipped by
   *       `activePhaseOf`, whatever its window says.
   */
  function setPhasePaused(uint256 _dropId, uint256 _phaseIndex, bool _paused) external;

  /**
   * @notice Adds or removes a wallet from a drop's allowlist. Only meaningful for phases using
   *         the Allowlist gate, but not restricted to them — a creator can populate the list
   *         before their gated phase opens, or keep curating it while the sale runs. Callable
   *         by the drop's creator (or their active burner session) only.
   */
  function setAllowlisted(uint256 _dropId, address _wallet, bool _allowed) external;

  /// @notice Batch version of setAllowlisted, for adding/removing several addresses in one tx.
  ///         Capped at MAX_BATCH_SIZE entries so a batch can never exceed the block gas limit
  ///         and revert with nothing written.
  function setAllowlistedBatch(uint256 _dropId, address[] calldata _wallets, bool _allowed) external;

  /**
   * @notice Re-points where the creator's share of each mint is sent — the HupCommunity
   *         payout model. Rules richer than "one wallet" (a split between collaborators, a
   *         treasury) live in the destination contract, not in this engine. address(0) clears
   *         it: proceeds go to the creator again. Takes effect for mints after this tx.
   * @dev Creator-only, and stricter than the drop's other levers: the call must come from the
   *      creator's own address, never a burner session or a forwarder relay. Session and relay
   *      identity both resolve through admin-rotatable references, so accepting them here would
   *      put a creator's revenue within reach of a compromised admin key. Proceeds are pushed,
   *      not escrowed, so a destination that can't
   *      receive native coin makes mints revert until this is changed — visible immediately,
   *      fixable in one tx, and only the creator's own drop is affected, which is why no
   *      escrow/claim ledger exists. The platform fee and referral share are unaffected.
   */
  function setPayoutDestination(uint256 _dropId, address _destination) external;

  /**
   * @notice Points mint proceeds at a split between `_payees`, deploying that split if it does
   *         not exist yet. The one-transaction form of `setPayoutDestination` for a drop whose
   *         creator is sharing the money.
   * @dev Creator-only on the same terms as `setPayoutDestination`. Shares are basis points and
   *      must total exactly 10 000. Splits are immutable, so changing who gets what later means
   *      pointing the drop at a different split, never editing this one.
   * @return split The split now receiving the creator's share of every mint.
   */
  function setPayoutSplit(uint256 _dropId, IHupSplits.Payee[] calldata _payees) external returns (address split);

  /**
   * @notice Appends one phase to a drop's schedule — the lane a creator forgot, or one the
   *         sale turned out to need. Callable by the drop's creator (or their active burner
   *         session) while the drop is open, up to MAX_PHASES in total.
   * @dev Appending is the only way a schedule ever changes. Existing phases stay untouchable,
   *      so nobody who already minted can have their terms moved; a new phase only ever adds a
   *      way to buy, and can never lift the drop's immutable `maxSupply`. Validated exactly as
   *      `createDrop` validates its own phases, and emits the same `PhaseConfigured` with the
   *      new index, so indexers need no new event.
   * @return phaseIndex The appended phase's index.
   */
  function addPhase(uint256 _dropId, PhaseInput calldata _phase) external returns (uint256 phaseIndex);

  /**
   * @notice Appends several phases in one transaction — a whole follow-up schedule in a single
   *         signature rather than one per lane.
   * @dev Same rules and the same PhaseConfigured event per entry as `addPhase`; the combined
   *      length still cannot exceed MAX_PHASES. All-or-nothing: one bad phase reverts the lot,
   *      so a creator can never end up with half a schedule.
   * @return firstPhaseIndex The index the first appended phase landed at; the rest follow it.
   */
  function addPhaseBatch(uint256 _dropId, PhaseInput[] calldata _phases) external returns (uint256 firstPhaseIndex);

  /**
   * @notice Closes a drop permanently. Callable by the drop's creator (or their active burner
   *         session) and by moderation admins. Remaining supply is forfeited; the collection
   *         contract itself is untouched.
   */
  function closeDrop(uint256 _dropId) external;

  // --- VIEW FUNCTIONS ---

  /**
   * @notice Returns a drop by id (zeroed struct when the id does not exist).
   */
  function getDrop(uint256 _dropId) external view returns (Drop memory);

  /**
   * @notice Returns a drop's full phase schedule, in index order.
   */
  function phasesOf(uint256 _dropId) external view returns (Phase[] memory);

  /**
   * @notice Returns the first phase whose time window is open right now and which its creator
   *         has not paused. `found` is false when no phase is live (upcoming, paused, between
   *         phases, or ended).
   */
  function activePhaseOf(uint256 _dropId) external view returns (bool found, uint256 index);

  /**
   * @notice Returns whether `_wallet` could mint `_quantity` through a phase right now — every
   *         check `mint` itself makes, gates included. What this returns, mint accepts.
   */
  function isMintable(uint256 _dropId, uint256 _phaseIndex, address _wallet, uint256 _quantity) external view returns (bool);

  /**
   * @notice How many wallets a drop's allowlist holds. Creator-gated like the paged listing —
   *         everyone else answers "is X on it" through the public `allowlist` getter.
   */
  function allowlistCount(uint256 _dropId) external view returns (uint256);

  /**
   * @notice One page of a drop's allowlist, for the creator's manage panel. Offset past the end
   *         or a zero limit returns an empty page rather than reverting.
   */
  function allowlistOf(uint256 _dropId, uint256 _offset, uint256 _limit) external view returns (address[] memory);

  // --- ADMIN CONFIGURATION ---

  function pause() external;
  function unpause() external;
  function setDeployer(uint256 _standardId, address _deployer) external;
  function setMintFeeBps(uint256 _mintFeeBps) external;
  function setMintFee(uint256 _mintFee) external;
  function setMintFeeEnabled(bool _enabled) external;
  function setCreationFee(uint256 _creationFee) external;
  function setFollowerSystem(address _followerSystem) external;
  function setCommunitySystem(address _communitySystem) external;
  function setSplits(address _splits) external;
  function setTrustedForwarder(address _forwarder, bool _trusted) external;
  function setHupContract(address _hupAddress) external;
  function withdrawAll(address payable _receiver) external;

  /**
   * @notice Sweeps the platform's accumulated fees in one ERC20 or LSP7 to `_receiver`.
   * @dev The native twin is `withdrawAll`. Token-priced phases accrue their fee here in that
   *      token, so each one needs its own sweep — there is no enumeration of which tokens the
   *      engine holds, by design: the admin knows what they priced drops in.
   */
  function withdrawToken(address _token, address _receiver, bool _isLsp7) external;
}

/**
 * @title IHupDropsDeployer
 * @notice A per-standard satellite holding one collection's creation code, so the engine stays
 *         under the EIP-170 size limit and future standards bolt on without redeploying it.
 * @dev `deploy` must revert for any caller but the engine it was constructed with.
 */
interface IHupDropsDeployer {
  function drops() external view returns (address);
  function deploy(address _creator, uint256 _maxSupply, bytes calldata _params) external returns (address collection);
}

/**
 * @title IHupDropCollection
 * @notice The uniform mint hook every drop collection exposes to the engine, whatever standard
 *         it speaks.
 * @dev `engineMint` must revert for any caller but the engine. Numbered standards (ERC721, LSP8)
 *      mint ids `_firstTokenId .. _firstTokenId + _quantity - 1`; edition standards (ERC1155,
 *      LSP7) mint `_quantity` units and ignore `_firstTokenId`.
 */
interface IHupDropCollection {
  function drops() external view returns (address);
  function maxSupply() external view returns (uint256);
  function totalMinted() external view returns (uint256);
  function engineMint(address _to, uint256 _firstTokenId, uint256 _quantity) external;
}

/**
 * @title ILSP26Minimal
 * @notice The single LSP26 Follower System call the Followers gate needs.
 */
interface ILSP26Minimal {
  function isFollowing(address follower, address addr) external view returns (bool);
}

/**
 * @title IHupCommunityMinimal
 * @notice The single HupCommunity call the Community gate needs. Its `registry` returns a
 *         wallet's full standing in one community; the gate reads membership and the ban flag
 *         and ignores the rest.
 */
interface IHupCommunityMinimal {
  function registry(uint256 id, address user) external view returns (bool isMember, bool isPending, bool isModerator, bool isBanned, bool canPost);
}

/**
 * @title IGateBalance
 * @notice Minimal `balanceOf` shared by ERC20, ERC721, LSP7, and LSP8 — one gate check covers
 *         all four.
 */
interface IGateBalance {
  function balanceOf(address account) external view returns (uint256);
}

/**
 * @title IGateBalance1155
 * @notice Id-scoped `balanceOf` for ERC1155 asset gates.
 */
interface IGateBalance1155 {
  function balanceOf(address account, uint256 id) external view returns (uint256);
}

/**
 * @title IERC2981Minimal
 * @notice The royalty read the engine uses to confirm a new collection points its resale
 *         royalties at the split the creator asked for. Every Hup drop collection answers it,
 *         whichever standard it speaks.
 */
interface IERC2981Minimal {
  function royaltyInfo(uint256 tokenId, uint256 salePrice) external view returns (address receiver, uint256 royaltyAmount);
}

v2/Extensions/IHupSplits.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.35;

/**
 * @title IHupSplits
 * @author Hup Labs
 * @notice Shared types, events, errors, and view signatures for the Hup Splits factory and the
 *         HupSplitter contracts it deploys.
 * @dev A split is addressed by its own table: the factory deploys through CREATE2 with the
 *      payee list in the initcode, so `predict` answers for a split that does not exist yet and
 *      the address itself proves the shares behind it. Anything that can hold value — a drop's
 *      payout destination, an ERC2981 royalty receiver, a community's fee destination — takes a
 *      split address without knowing anything about splits.
 * @custom:website https://hup.social
 * @custom:security-contact security@hup.social
 */
interface IHupSplits {
  // --- STRUCTS ---

  /**
   * @notice One share of a split.
   * @dev Packed into a single slot: 20 bytes of address next to 2 of basis points.
   */
  struct Payee {
    address account;
    uint16 shareBps;
  }

  // --- EVENTS ---

  /// @notice A split's table, published once at deployment — the only place it is ever written.
  event SplitCreated(address indexed split, address indexed by, Payee[] payees);

  // --- ERRORS ---

  error InvalidAddress();
  error InvalidPayees();
  error InvalidShares(uint256 total);
  error DuplicatePayee(address account);

  // --- VIEW FUNCTIONS ---

  function version() external pure returns (string memory);

  /// @notice Whether this factory deployed `_split`.
  function isSplit(address _split) external view returns (bool);

  /// @notice Total splits this factory has deployed.
  function splitCount() external view returns (uint256);

  /**
   * @notice The address `_payees` splits to, deployed or not. Value sent to it before it exists
   *         is held at the address and is spendable the moment `create` materializes it.
   */
  function predict(Payee[] calldata _payees) external view returns (address split);

  // --- LOGIC ---

  /**
   * @notice Deploys the split for `_payees`, or returns the existing one — the same table always
   *         resolves to the same address, so calling twice costs one deployment.
   */
  function create(Payee[] calldata _payees) external returns (address split);
}

